AssistantMessageToolRequest(name='create', tool_call_id='tooluse_JPecVy12LgofILyT2N02uS', arguments={'file_text': '/* ============================================================================
   Base Styles & Variables
   ============================================================================ */

:root {
    --color-primary: #1a1a1a;
    --color-secondary: #ffffff;
    --color-accent: #d4a574;
    --color-neutral-dark: #333333;
    --color-neutral-light: #f5f5f5;
    --color-neutral-lighter: #fafafa;
    --color-text: #1a1a1a;
    --color-text-secondary: #666666;
    --color-border: #e8e8e8;
    --color-error: #dc2626;
    --color-success: #16a34a;

    --spacing-xs: 0.5rem;
    --spacing-sm: 0.75rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 3rem;
    --spacing-3xl: 4rem;

    --border-radius: 8px;
    --border-radius-lg: 12px;

    --font-family-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
    --font-family-serif: 'Georgia', 'Garamond', serif;

    --font-size-xs: 0.75rem;
    --font-size-sm: 0.875rem;
    --font-size-base: 1rem;
    --font-size-lg: 1.125rem;
    --font-size-xl: 1.5rem;
    --font-size-2xl: 2rem;
    --font-size-3xl: 2.5rem;

    --line-height-tight: 1.3;
    --line-height-normal: 1.5;
    --line-height-relaxed: 1.75;

    --transition-fast: 150ms ease-in-out;
    --transition-base: 250ms ease-in-out;
    --transition-slow: 350ms ease-in-out;

    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.1);
}

@media (prefers-reduced-motion: reduce) {
    :root {
        --transition-fast: 0ms;
        --transition-base: 0ms;
        --transition-slow: 0ms;
    }
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-family-sans);
    font-size: var(--font-size-base);
    line-height: var(--line-height-normal);
    color: var(--color-text);
    background-color: var(--color-secondary);
}

/* ============================================================================
   Skip Link
   ============================================================================ */

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background-color: var(--color-primary);
    color: var(--color-secondary);
    padding: var(--spacing-md) var(--spacing-lg);
    text-decoration: none;
    z-index: 100;
    border-radius: var(--border-radius);
}

.skip-link:focus {
    top: 0;
    outline: 3px solid var(--color-accent);
    outline-offset: 2px;
}

/* ============================================================================
   Visually Hidden (for screen readers only)
   ============================================================================ */

.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* ============================================================================
   Typography
   ============================================================================ */

h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    line-height: var(--line-height-tight);
    margin-bottom: var(--spacing-md);
}

h1 {
    font-size: var(--font-size-3xl);
}

h2 {
    font-size: var(--font-size-2xl);
}

h3 {
    font-size: var(--font-size-lg);
}

p {
    margin-bottom: var(--spacing-md);
    color: var(--color-text-secondary);
}

a {
    color: var(--color-primary);
    text-decoration: none;
    transition: color var(--transition-fast);
}

a:hover, a:focus {
    color: var(--color-accent);
}

a:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* ============================================================================
   Buttons
   ============================================================================ */

button {
    font-family: var(--font-family-sans);
    font-size: var(--font-size-base);
    cursor: pointer;
    border: none;
    padding: 0;
    background: none;
}

.btn {
    padding: var(--spacing-md) var(--spacing-lg);
    border-radius: var(--border-radius);
    font-weight: 600;
    transition: all var(--transition-fast);
    display: inline-block;
    text-align: center;
    border: 2px solid transparent;
    min-width: 120px;
    cursor: pointer;
    text-decoration: none;
}

.btn:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.btn-primary {
    background-color: var(--color-primary);
    color: var(--color-secondary);
}

.btn-primary:hover {
    background-color: var(--color-neutral-dark);
    transform: translateY(-2px);
}

.btn-primary:active {
    transform: translateY(0);
}

.btn-secondary {
    background-color: var(--color-secondary);
    color: var(--color-primary);
    border-color: var(--color-border);
}

.btn-secondary:hover {
    background-color: var(--color-neutral-lighter);
    border-color: var(--color-primary);
}

.btn-accent {
    background-color: var(--color-accent);
    color: var(--color-secondary);
}

.btn-accent:hover {
    background-color: #c4934a;
    transform: translateY(-2px);
}

.icon-button {
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--border-radius);
    color: var(--color-primary);
    transition: background-color var(--transition-fast);
}

.icon-button:hover {
    background-color: var(--color-neutral-light);
}

.icon-button:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* ============================================================================
   Header & Navigation
   ============================================================================ */

.header {
    background-color: var(--color-secondary);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-md) var(--spacing-lg);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.logo {
    font-size: var(--font-size-xl);
    font-weight: 700;
    letter-spacing: -0.5px;
    margin: 0;
}

.primary-nav {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.nav-toggle {
    display: none;
    width: 44px;
    height: 44px;
    flex-direction: column;
    justify-content: center;
    gap: 6px;
}

.nav-toggle span {
    width: 24px;
    height: 2px;
    background-color: var(--color-primary);
    border-radius: 1px;
    transition: all var(--transition-fast);
}

.nav-toggle[aria-expanded="true"] span:first-child {
    transform: rotate(45deg) translateY(10px);
}

.nav-toggle[aria-expanded="true"] span:nth-child(2) {
    opacity: 0;
}

.nav-toggle[aria-expanded="true"] span:last-child {
    transform: rotate(-45deg) translateY(-10px);
}

.nav-menu {
    list-style: none;
    display: flex;
    gap: var(--spacing-2xl);
}

.nav-menu a {
    font-weight: 500;
    display: block;
    padding: var(--spacing-sm) 0;
    border-bottom: 2px solid transparent;
    transition: all var(--transition-fast);
}

.nav-menu a:hover, .nav-menu a:focus {
    border-bottom-color: var(--color-accent);
    color: var(--color-accent);
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
    align-items: center;
}

/* ============================================================================
   Main Layout
   ============================================================================ */

main {
    min-height: calc(100vh - 100px);
}

.section-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

section {
    padding: var(--spacing-3xl) var(--spacing-lg);
}

section h2 {
    margin-bottom: var(--spacing-2xl);
    text-align: center;
}

/* ============================================================================
   Hero Section
   ============================================================================ */

.hero {
    background: linear-gradient(135deg, #f5f5f5 0%, #fafafa 100%);
    min-height: 500px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-3xl);
    padding: var(--spacing-3xl) var(--spacing-lg);
}

.hero-content {
    flex: 1;
    max-width: 600px;
}

.hero h2 {
    font-size: var(--font-size-3xl);
    margin-bottom: var(--spacing-lg);
    text-align: left;
}

.hero p {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-2xl);
}

.hero-image {
    flex: 1;
    min-height: 400px;
    background: linear-gradient(45deg, #e8e8e8 0%, #d8d8d8 100%);
    border-radius: var(--border-radius-lg);
}

/* ============================================================================
   Products Grid
   ============================================================================ */

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-2xl);
}

.product-card {
    background-color: var(--color-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    aspect-ratio: 1;
    overflow: hidden;
    background-color: var(--color-neutral-light);
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    flex: 1;
}

.product-info h3 {
    margin: 0;
    font-size: var(--font-size-lg);
}

.product-description {
    margin: 0;
    font-size: var(--font-size-sm);
    color: var(--color-text-secondary);
}

.product-rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-size-sm);
}

.stars {
    color: #fbbf24;
}

.rating-count {
    color: var(--color-text-secondary);
}

.product-price {
    font-size: var(--font-size-lg);
    font-weight: 600;
}

.product-card .btn {
    width: 100%;
    margin-top: auto;
}

/* ============================================================================
   Deals Section
   ============================================================================ */

.deals-section {
    background-color: var(--color-neutral-lighter);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-2xl);
}

.deal-card {
    background: linear-gradient(135deg, var(--color-secondary) 0%, var(--color-neutral-light) 100%);
    border-radius: var(--border-radius-lg);
    padding: var(--spacing-2xl);
    position: relative;
    overflow: hidden;
    border: 1px solid var(--color-border);
    transition: all var(--transition-base);
}

.deal-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.deal-badge {
    position: absolute;
    top: -20px;
    right: -20px;
    width: 120px;
    height: 120px;
    background-color: var(--color-accent);
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: var(--color-secondary);
    font-weight: 700;
    box-shadow: var(--shadow-md);
}

.discount-percent {
    font-size: var(--font-size-2xl);
    line-height: 1;
}

.discount-label {
    font-size: var(--font-size-sm);
}

.deal-content {
    position: relative;
    z-index: 1;
}

.deal-content h3 {
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-lg);
}

.deal-content p {
    margin-bottom: var(--spacing-lg);
}

.deal-timer {
    margin-bottom: var(--spacing-lg);
    font-weight: 600;
}

.timer-label {
    color: var(--color-text-secondary);
}

.timer-display {
    color: var(--color-accent);
    font-family: 'Courier New', monospace;
    font-size: var(--font-size-lg);
}

.deal-card .btn {
    width: 100%;
}

/* ============================================================================
   Editorial Section
   ============================================================================ */

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-2xl);
}

.editorial-card {
    background-color: var(--color-secondary);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    transition: all var(--transition-base);
}

.editorial-card:hover {
    box-shadow: var(--shadow-lg);
}

.editorial-image {
    width: 100%;
    aspect-ratio: 4 / 3;
    overflow: hidden;
    background-color: var(--color-neutral-light);
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.08);
}

.editorial-content {
    padding: var(--spacing-lg);
}

.article-category {
    display: inline-block;
    font-size: var(--font-size-xs);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--color-accent);
    margin-bottom: var(--spacing-md);
}

.editorial-content h3 {
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-lg);
}

.editorial-content p {
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-sm);
}

.read-more {
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-weight: 600;
    color: var(--color-primary);
}

.read-more:hover, .read-more:focus {
    color: var(--color-accent);
}

/* ============================================================================
   Newsletter Section
   ============================================================================ */

.newsletter-section {
    background: linear-gradient(135deg, var(--color-primary) 0%, #2a2a2a 100%);
    color: var(--color-secondary);
}

.newsletter-section h2 {
    color: var(--color-secondary);
    margin-bottom: var(--spacing-md);
}

.newsletter-section > .section-container > p {
    color: rgba(255, 255, 255, 0.8);
    margin-bottom: var(--spacing-2xl);
    font-size: var(--font-size-lg);
}

.newsletter-form {
    max-width: 500px;
    margin: 0 auto var(--spacing-lg);
    display: flex;
    gap: var(--spacing-md);
}

.form-group {
    flex: 1;
    position: relative;
}

.form-group input {
    width: 100%;
    padding: var(--spacing-md);
    border: none;
    border-radius: var(--border-radius);
    font-family: var(--font-family-sans);
    font-size: var(--font-size-base);
}

.form-group input:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.form-group input::placeholder {
    color: var(--color-text-secondary);
}

.error-message {
    position: absolute;
    bottom: -25px;
    left: 0;
    font-size: var(--font-size-sm);
    color: #fca5a5;
    display: none;
}

.error-message.show {
    display: block;
}

.form-hint {
    text-align: center;
    font-size: var(--font-size-sm);
    color: rgba(255, 255, 255, 0.7);
    margin: 0;
}

.newsletter-form .btn {
    white-space: nowrap;
    min-width: 130px;
}

/* ============================================================================
   Footer
   ============================================================================ */

.footer {
    background-color: var(--color-primary);
    color: var(--color-secondary);
    padding: var(--spacing-3xl) var(--spacing-lg) var(--spacing-lg);
}

.footer-container {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-3xl);
    margin-bottom: var(--spacing-3xl);
}

.footer-section h3 {
    color: var(--color-secondary);
    margin-bottom: var(--spacing-lg);
    font-size: var(--font-size-base);
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: var(--spacing-md);
}

.footer-section a {
    color: rgba(255, 255, 255, 0.7);
    transition: color var(--transition-fast);
}

.footer-section a:hover, .footer-section a:focus {
    color: var(--color-accent);
}

.social-links {
    display: flex;
    gap: var(--spacing-lg);
}

.social-links a {
    padding: var(--spacing-sm) 0;
}

.footer-bottom {
    max-width: 1400px;
    margin: 0 auto;
    padding-top: var(--spacing-lg);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    text-align: center;
    color: rgba(255, 255, 255, 0.6);
    font-size: var(--font-size-sm);
}

/* ============================================================================
   Responsive Design
   ============================================================================ */

@media (max-width: 768px) {
    :root {
        --font-size-xl: 1.25rem;
        --font-size-2xl: 1.75rem;
        --font-size-3xl: 2rem;
        --spacing-3xl: 2.5rem;
    }

    section {
        padding: var(--spacing-2xl) var(--spacing-md);
    }

    .header-container {
        padding: var(--spacing-md);
    }

    .nav-toggle {
        display: flex;
    }

    .nav-menu {
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background-color: var(--color-secondary);
        flex-direction: column;
        gap: var(--spacing-md);
        padding: var(--spacing-lg);
        max-height: 0;
        overflow: hidden;
        transition: max-height var(--transition-base);
        border-bottom: 1px solid var(--color-border);
    }

    .nav-menu[aria-expanded="true"] {
        max-height: 400px;
    }

    .primary-nav {
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background-color: var(--color-secondary);
        flex-direction: column;
        border-bottom: 1px solid var(--color-border);
    }

    .hero {
        flex-direction: column;
        min-height: auto;
        padding: var(--spacing-2xl) var(--spacing-md);
    }

    .hero-image {
        min-height: 300px;
    }

    .header-actions {
        gap: var(--spacing-sm);
    }

    .icon-button {
        width: 40px;
        height: 40px;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: var(--spacing-lg);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form .btn {
        width: 100%;
    }

    .footer-container {
        grid-template-columns: 1fr;
        gap: var(--spacing-2xl);
    }
}

@media (max-width: 480px) {
    :root {
        --font-size-lg: 1rem;
        --font-size-xl: 1.125rem;
        --font-size-2xl: 1.5rem;
        --font-size-3xl: 1.75rem;
        --spacing-2xl: 2rem;
        --spacing-3xl: 1.5rem;
    }

    .header-container {
        padding: var(--spacing-sm);
        gap: var(--spacing-sm);
    }

    .logo {
        font-size: var(--font-size-lg);
    }

    section {
        padding: var(--spacing-xl) var(--spacing-md);
    }

    section h2 {
        margin-bottom: var(--spacing-lg);
    }

    .hero {
        padding: var(--spacing-xl) var(--spacing-md);
    }

    .hero p {
        margin-bottom: var(--spacing-lg);
    }

    .products-grid {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
    }

    .product-card:hover {
        transform: translateY(-2px);
    }

    .deal-card:hover {
        transform: translateY(-2px);
    }

    .btn {
        min-width: 100px;
        padding: var(--spacing-sm) var(--spacing-md);
    }
}

/* ============================================================================
   Contrast & Color Mode Support
   ============================================================================ */

@media (prefers-contrast: more) {
    :root {
        --color-border: #cccccc;
    }

    .btn-primary {
        border: 2px solid var(--color-secondary);
    }

    .btn-secondary {
        border: 2px solid var(--color-primary);
    }

    a {
        text-decoration: underline;
    }
}

@media (prefers-color-scheme: dark) {
    :root {
        --color-secondary: #1a1a1a;
        --color-primary: #ffffff;
        --color-neutral-light: #2a2a2a;
        --color-neutral-lighter: #333333;
        --color-text: #ffffff;
        --color-text-secondary: #b0b0b0;
        --color-border: #333333;
    }

    body {
        background-color: var(--color-secondary);
    }

    .hero {
        background: linear-gradient(135deg, #222 0%, #1a1a1a 100%);
    }

    .hero-image {
        background: linear-gradient(45deg, #333 0%, #2a2a2a 100%);
    }

    .product-image {
        background-color: var(--color-neutral-light);
    }

    .deals-section {
        background-color: #0d0d0d;
    }

    .deal-card {
        background: linear-gradient(135deg, #1a1a1a 0%, #242424 100%);
    }
}

@media (forced-colors: active) {
    :root {
        --color-accent: Highlight;
        --color-primary: ButtonText;
        --color-secondary: ButtonFace;
    }

    .btn, a, button {
        border: 1px solid ButtonBorder;
    }

    .btn:focus, a:focus, button:focus {
        outline: 2px solid Highlight;
    }

    .skip-link:focus {
        outline: 3px solid Highlight;
    }
}
