/* ============================================================================
   Mobile Navigation
   ============================================================================ */

function initializeNavigation() {
    const navToggle = document.querySelector('.nav-toggle');
    const navMenu = document.getElementById('nav-menu');

    if (!navToggle || !navMenu) return;

    navToggle.addEventListener('click', () => {
        const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
        navToggle.setAttribute('aria-expanded', !isExpanded);
    });

    // Close menu when a link is clicked
    navMenu.querySelectorAll('a').forEach(link => {
        link.addEventListener('click', () => {
            navToggle.setAttribute('aria-expanded', 'false');
        });
    });

    // Close menu when clicking outside
    document.addEventListener('click', (e) => {
        if (!e.target.closest('.primary-nav')) {
            navToggle.setAttribute('aria-expanded', 'false');
        }
    });

    // Close menu on Escape
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            navToggle.setAttribute('aria-expanded', 'false');
        }
    });
}

/* ============================================================================
   Product Add to Cart
   ============================================================================ */

function initializeProductCards() {
    const buttons = document.querySelectorAll('.product-card .btn-secondary');

    buttons.forEach(button => {
        button.addEventListener('click', (e) => {
            e.preventDefault();

            const card = button.closest('.product-card');
            const productName = card.querySelector('h3').textContent;

            // Show feedback
            const originalText = button.textContent;
            button.textContent = 'Added to Cart! ✓';
            button.disabled = true;

            setTimeout(() => {
                button.textContent = originalText;
                button.disabled = false;
            }, 2000);

            // Log for demo
            console.log(`Added "${productName}" to cart`);
        });
    });
}

/* ============================================================================
   Deal Timers
   ============================================================================ */

function initializeDealTimers() {
    const timerDisplays = document.querySelectorAll('.timer-display');

    function updateTimers() {
        timerDisplays.forEach(display => {
            const timeString = display.textContent;
            const [hours, minutes, seconds] = timeString.split(':').map(Number);

            let totalSeconds = hours * 3600 + minutes * 60 + seconds - 1;

            if (totalSeconds < 0) {
                display.textContent = 'Expired';
                display.closest('.deal-timer').setAttribute('aria-live', 'assertive');
                return;
            }

            const h = Math.floor(totalSeconds / 3600);
            const m = Math.floor((totalSeconds % 3600) / 60);
            const s = totalSeconds % 60;

            display.textContent = 
                `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
        });
    }

    // Update every second
    setInterval(updateTimers, 1000);
}

/* ============================================================================
   Newsletter Form
   ============================================================================ */

function initializeNewsletter() {
    const form = document.querySelector('.newsletter-form');
    const emailInput = document.getElementById('email');
    const errorMessage = document.getElementById('email-error');

    if (!form || !emailInput) return;

    function validateEmail(email) {
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return re.test(email);
    }

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const email = emailInput.value.trim();

        // Clear previous error
        errorMessage.classList.remove('show');
        errorMessage.textContent = '';

        if (!email) {
            errorMessage.textContent = 'Please enter your email address';
            errorMessage.classList.add('show');
            emailInput.focus();
            return;
        }

        if (!validateEmail(email)) {
            errorMessage.textContent = 'Please enter a valid email address';
            errorMessage.classList.add('show');
            emailInput.focus();
            return;
        }

        // Show success
        const button = form.querySelector('button');
        const originalText = button.textContent;
        button.textContent = 'Subscribed! ✓';
        button.disabled = true;

        // Reset form
        emailInput.value = '';

        setTimeout(() => {
            button.textContent = originalText;
            button.disabled = false;
        }, 3000);

        console.log(`Subscribed: ${email}`);
    });

    // Clear error on input
    emailInput.addEventListener('input', () => {
        if (errorMessage.classList.contains('show')) {
            errorMessage.classList.remove('show');
            errorMessage.textContent = '';
        }
    });
}

