    background-color: var(--color-neutral-light);
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    flex: 1;
}

.product-info h3 {
    margin: 0;
    font-size: var(--font-size-lg);
}

.product-description {
    margin: 0;
    font-size: var(--font-size-sm);
    color: var(--color-text-secondary);
}

.product-rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-size-sm);
}

.stars {
    color: #fbbf24;
}

.rating-count {
    color: var(--color-text-secondary);
}

.product-price {
    font-size: var(--font-size-lg);
    font-weight: 600;
}

.product-card .btn {
    width: 100%;
    margin-top: auto;
}

/* ============================================================================
   Deals Section
   ============================================================================ */

.deals-section {
    background-color: var(--color-neutral-lighter);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-2xl);
}

.deal-card {
    background: linear-gradient(135deg, var(--color-secondary) 0%, var(--color-neutral-light) 100%);
    border-radius: var(--border-radius-lg);
    padding: var(--spacing-2xl);
    position: relative;
    overflow: hidden;
    border: 1px solid var(--color-border);
    transition: all var(--transition-base);
}

.deal-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.deal-badge {
    position: absolute;
    top: -20px;
    right: -20px;
    width: 120px;
    height: 120px;
    background-color: var(--color-accent);
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: var(--color-secondary);
    font-weight: 700;
    box-shadow: var(--shadow-md);
}

.discount-percent {
    font-size: var(--font-size-2xl);
    line-height: 1;
}

.discount-label {
    font-size: var(--font-size-sm);
}

.deal-content {
    position: relative;
    z-index: 1;
}

.deal-content h3 {
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-lg);
}

.deal-content p {
    margin-bottom: var(--spacing-lg);
}

.deal-timer {
    margin-bottom: var(--spacing-lg);
    font-weight: 600;
}

.timer-label {
    color: var(--color-text-secondary);
}

.timer-display {
    color: var(--color-accent);
    font-family: 'Courier New', monospace;
    font-size: var(--font-size-lg);
}

.deal-card .btn {
    width: 100%;
}

/* ============================================================================
   Editorial Section
   ============================================================================ */

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-2xl);
}

.editorial-card {
    background-color: var(--color-secondary);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    transition: all var(--transition-base);
}

.editorial-card:hover {
    box-shadow: var(--shadow-lg);
}

.editorial-image {
    width: 100%;
    aspect-ratio: 4 / 3;
    overflow: hidden;
    background-color: var(--color-neutral-light);
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.08);
}

.editorial-content {
    padding: var(--spacing-lg);
}

.article-category {
    display: inline-block;
    font-size: var(--font-size-xs);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--color-accent);
    margin-bottom: var(--spacing-md);
}

.editorial-content h3 {
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-lg);
}

.editorial-content p {
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-sm);
}

.read-more {
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-weight: 600;
    color: var(--color-primary);
}

.read-more:hover, .read-more:focus {
    color: var(--color-accent);
}

/* ============================================================================
   Newsletter Section
   ============================================================================ */

.newsletter-section {
    background: linear-gradient(135deg, var(--color-primary) 0%, #2a2a2a 100%);
    color: var(--color-secondary);
