const fs = require('fs');
const path = require('path');

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.join(__dirname, 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf-8');

    await page.setContent(html, { waitUntil: 'load' });
    await page.addScriptTag({ path: '/tmp/axe.min.js' });

    const result = await page.evaluate(async () => {
        return await window.axe.run();
    });

    await browser.close();

    const wcag = result.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = result.violations.filter(v => v.tags.includes('best-practice'));

    console.log('=== ACCESSIBILITY TEST RESULTS ===\n');
    console.log(`Total violations: ${result.violations.length}`);
    console.log(`WCAG violations: ${wcag.length}`);
    console.log(`Best-practice warnings: ${bp.length}`);
    console.log(`Passes: ${result.passes.length}\n`);

    if (wcag.length > 0) {
        console.log('WCAG VIOLATIONS:');
        wcag.forEach(v => {
            console.log(`\n  ID: ${v.id} (${v.impact})`);
            console.log(`  Description: ${v.description}`);
            console.log(`  Elements: ${v.nodes.map(n => n.target).join(', ')}`);
        });
    }

    if (bp.length > 0) {
        console.log('\nBEST-PRACTICE WARNINGS:');
        bp.forEach(v => {
            console.log(`\n  ID: ${v.id}`);
            console.log(`  Description: ${v.description}`);
            console.log(`  Elements: ${v.nodes.map(n => n.target).join(', ')}`);
        });
    }

    process.exit(wcag.length > 0 ? 1 : 0);
})();
